from random import random

def tir(p):
    if random() < p:
        return 1
    return 0

def serie(n, p):
    resultats = []
    for i in range(n):
        resultats.append(tir(p))
    return resultats

from math import comb

def risque(n):
    cumul = 0
    for k in range(51):
        cumul = cumul + comb(n, k) * 0.9**k * 0.1**(n - k)
    return 1 - cumul
